const TAB_MESSAGE_TRANSPORT_CLASSES = new Set([
  "NO_RECEIVER",
  "PORT_CLOSED",
  "TAB_GONE",
  "CONTEXT_INVALIDATED",
  "SYNC_SEND_EXCEPTION",
  "OTHER_TAB_MESSAGE_ERROR",
  "RESPONSE_TIMEOUT"
]);
const TAB_IDENTITY_RESPONSE_TIMEOUT_MS = 3000;

function safeTabMessageTransportClass(value) {
  const candidate = typeof value === "string" ? value : "";
  return TAB_MESSAGE_TRANSPORT_CLASSES.has(candidate) ? candidate : null;
